Use the binomial theorem to expand $(x+2)^{4}$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\draw[rounded corners=4pt, thick, fill=gray!15] (-2.65,-3.75) rectangle (2.65,-3.05);
\node[anchor=east] at (-3,0) {$n = 0$};
\node at (0,0) {$1$};
\node[anchor=east] at (-3,-0.85) {$n = 1$};
\node at (-0.55,-0.85) {$1$};
\node at (0.55,-0.85) {$1$};
\node[anchor=east] at (-3,-1.7) {$n = 2$};
\node at (-1.1,-1.7) {$1$};
\node at (0,-1.7) {$2$};
\node at (1.1,-1.7) {$1$};
\node[anchor=east] at (-3,-2.55) {$n = 3$};
\node at (-1.65,-2.55) {$1$};
\node at (-0.55,-2.55) {$3$};
\node at (0.55,-2.55) {$3$};
\node at (1.65,-2.55) {$1$};
\node[anchor=east] at (-3,-3.4) {$n = 4$};
\node at (-2.2,-3.4) {$1$};
\node at (-1.1,-3.4) {$4$};
\node at (0,-3.4) {$6$};
\node at (1.1,-3.4) {$4$};
\node at (2.2,-3.4) {$1$};
